CREATE TABLE role (name varchar(20) PRIMARY KEY);
INSERT INTO role VALUES ('STUDENT'),('TEACHER'),('COORDINATOR'),('ADMIN');
CREATE TABLE app_user (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 name varchar(120) NOT NULL, email varchar(200) NOT NULL UNIQUE CHECK(email=lower(email)),
 password_hash varchar(100) NOT NULL, role varchar(20) NOT NULL REFERENCES role(name),
 active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT false,
 auth_version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE period (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL UNIQUE, starts_on date NOT NULL, ends_on date NOT NULL, CHECK(ends_on>=starts_on));
CREATE TABLE grade (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(80) NOT NULL UNIQUE);
CREATE TABLE section (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(80) NOT NULL UNIQUE);
CREATE TABLE subject (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL UNIQUE, color varchar(7) NOT NULL DEFAULT '#2563eb');
CREATE TABLE study_group (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, period_id bigint NOT NULL REFERENCES period, grade_id bigint NOT NULL REFERENCES grade, section_id bigint NOT NULL REFERENCES section, UNIQUE(period_id,grade_id,section_id));
CREATE TABLE enrollment (student_id bigint NOT NULL REFERENCES app_user, group_id bigint NOT NULL REFERENCES study_group, PRIMARY KEY(student_id,group_id));
CREATE TABLE coordinator_scope (user_id bigint NOT NULL REFERENCES app_user, group_id bigint NOT NULL REFERENCES study_group, can_manage boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,group_id));
CREATE TABLE course (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_id bigint NOT NULL REFERENCES subject, group_id bigint NOT NULL REFERENCES study_group, teacher_id bigint NOT NULL REFERENCES app_user, UNIQUE(subject_id,group_id));
CREATE INDEX course_teacher_idx ON course(teacher_id);
CREATE INDEX enrollment_group_idx ON enrollment(group_id);
CREATE TABLE schedule (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES course, weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts_at time NOT NULL, ends_at time NOT NULL, modality varchar(20) NOT NULL CHECK(modality IN ('PRESENCIAL','VIRTUAL','HIBRIDA')), url varchar(2000), CHECK(ends_at>starts_at));
CREATE INDEX schedule_course_idx ON schedule(course_id);
CREATE TABLE task (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES course, title varchar(180) NOT NULL, description text NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, delivery_type varchar(10) NOT NULL CHECK(delivery_type IN ('FILE','LINK','BOTH')), max_score numeric(6,2) NOT NULL CHECK(max_score>0 AND max_score<=1000));
CREATE INDEX task_course_idx ON task(course_id,due_at);
CREATE TABLE stored_file (id uuid PRIMARY KEY, course_id bigint NOT NULL REFERENCES course, owner_id bigint NOT NULL REFERENCES app_user, purpose varchar(20) NOT NULL CHECK(purpose IN ('RESOURCE','TASK','SUBMISSION')), name varchar(180) NOT NULL, mime varchar(100) NOT NULL, content bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(octet_length(content)<=5242880));
CREATE INDEX stored_file_course_idx ON stored_file(course_id);
CREATE TABLE task_file (task_id bigint NOT NULL REFERENCES task, file_id uuid NOT NULL UNIQUE REFERENCES stored_file, PRIMARY KEY(task_id,file_id));
CREATE TABLE submission (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id bigint NOT NULL REFERENCES task, student_id bigint NOT NULL REFERENCES app_user, file_id uuid REFERENCES stored_file, url varchar(2000), submitted_at timestamptz NOT NULL DEFAULT now(), score numeric(6,2), feedback text, graded_at timestamptz, UNIQUE(task_id,student_id), CHECK(file_id IS NOT NULL OR url IS NOT NULL));
CREATE INDEX submission_student_idx ON submission(student_id);
CREATE TABLE resource (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES course, title varchar(180) NOT NULL, unit varchar(100) NOT NULL, body text NOT NULL DEFAULT '', url varchar(2000), file_id uuid REFERENCES stored_file, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE message (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES course, sender_id bigint NOT NULL REFERENCES app_user, body varchar(3000) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX message_course_idx ON message(course_id,id);
CREATE TABLE notice (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id bigint NOT NULL REFERENCES study_group, author_id bigint NOT NULL REFERENCES app_user, title varchar(180) NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES app_user, title varchar(220) NOT NULL, course_id bigint REFERENCES course, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notification_user_idx ON notification(user_id,id);
CREATE TABLE audit_log (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id bigint REFERENCES app_user, action varchar(100) NOT NULL, target varchar(180) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
